/* Helpers */
function SectionHeader({ label, title }) {
  return (
    <div>
      <p style={{ fontFamily: "'DM Sans', sans-serif", fontSize: 13, fontWeight: 600, color: "#7c3aed", textTransform: "uppercase", letterSpacing: "0.12em", marginBottom: 12 }}>{label}</p>
      <h2 style={{ fontFamily: "'Syne', sans-serif", fontWeight: 800, fontSize: "clamp(36px, 4vw, 52px)", letterSpacing: "-0.025em", lineHeight: 1.1, color: "#0f172a" }}>{title}</h2>
    </div>
  );
}

function SectionObserver({ children }) {
  const ref = useRef(null);
  const [inView, setInView] = useState(false);

  useEffect(() => {
    const obs = new IntersectionObserver(([e]) => { if (e.isIntersecting) setInView(true); }, { threshold: 0.1 });
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, []);

  return (
    <div ref={ref} className={`section-fade${inView ? " in" : ""}`}>
      {children}
    </div>
  );
}
